export type Item = { sku: string; price: number; qty: number };

/** calcTotal: sum of price × quantity over the cart. shippingFee: shipping for the cart, in dollars. */
export function calcTotal(items: Item[]): number {
  const total = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const quantity = items.reduce((sum, item) => sum + item.qty, 0);
  return quantity >= 10 ? total * 0.9 : total;
}
export function shippingFee(items: Item[]): number { return !items.length || calcTotal(items) >= 50 ? 0 : 6; }

